    function drawCurveLab() {
      const canvas = document.getElementById("curveLabCanvas");
      if (!canvas) return;
      const ctx = canvas.getContext("2d");
      const w = canvas.width;
      const h = canvas.height;

      const tau1 = parseFloat(document.getElementById("sliderTau1").value);
      const tau2 = parseFloat(document.getElementById("sliderTau2").value);
      const noiseLvl = parseInt(document.getElementById("sliderNoise").value);

      document.getElementById("valTau1").innerText = tau1.toFixed(1) + " ns";
      document.getElementById("valTau2").innerText = tau2.toFixed(1) + " ns";
      document.getElementById("valNoise").innerText = (noiseLvl / 100).toFixed(2) + (noiseLvl <= 6 ? " (高精)" : " (常规)");

      const r2 = Math.max(0.912, (0.996 - noiseLvl * 0.0022)).toFixed(4);
      document.getElementById("liveR2Readout").innerText = "R² = " + r2;

      ctx.clearRect(0, 0, w, h);

      ctx.fillStyle = "#040814";
      ctx.fillRect(0, 0, w, h);
      ctx.strokeStyle = "rgba(30, 41, 59, 0.75)";
      ctx.lineWidth = 1;
      for (let x = 40; x < w; x += 48) {
        ctx.beginPath(); ctx.moveTo(x, 12); ctx.lineTo(x, h - 24); ctx.stroke();
      }
      for (let y = 20; y < h - 20; y += 36) {
        ctx.beginPath(); ctx.moveTo(40, y); ctx.lineTo(w - 16, y); ctx.stroke();
      }

      ctx.strokeStyle = "#475569";
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.moveTo(40, 12); ctx.lineTo(40, h - 24); ctx.lineTo(w - 14, h - 24);
      ctx.stroke();

      ctx.fillStyle = "rgba(6, 182, 212, 0.14)";
      ctx.beginPath();
      for (let px = 40; px <= w - 20; px += 4) {
        const t = ((px - 40) / (w - 60)) * 200;
        const yVal = 0.55 * Math.exp(-t / tau1) + 0.45 * Math.exp(-t / tau2);
        const py = (h - 28) - yVal * (h - 52) - (noiseLvl * 1.1);
        if (px === 40) ctx.moveTo(px, py); else ctx.lineTo(px, py);
      }
      for (let px = w - 20; px >= 40; px -= 4) {
        const t = ((px - 40) / (w - 60)) * 200;
        const yVal = 0.55 * Math.exp(-t / tau1) + 0.45 * Math.exp(-t / tau2);
        const py = (h - 28) - yVal * (h - 52) + (noiseLvl * 1.1);
        ctx.lineTo(px, py);
      }
      ctx.closePath();
      ctx.fill();

      ctx.strokeStyle = "#22d3ee";
      ctx.lineWidth = 2.5;
      ctx.beginPath();
      for (let px = 40; px <= w - 20; px += 3) {
        const t = ((px - 40) / (w - 60)) * 200;
        const yVal = 0.55 * Math.exp(-t / tau1) + 0.45 * Math.exp(-t / tau2);
        const py = (h - 28) - yVal * (h - 52);
        if (px === 40) ctx.moveTo(px, py); else ctx.lineTo(px, py);
      }
      ctx.stroke();

      for (let i = 0; i <= 22; i++) {
        const px = 44 + i * ((w - 68) / 22);
        const t = ((px - 40) / (w - 60)) * 200;
        const yVal = 0.55 * Math.exp(-t / tau1) + 0.45 * Math.exp(-t / tau2);
        const pseudoOffset = Math.sin(i * 2.7 + tau1) * (noiseLvl * 1.2);
        const py = (h - 28) - yVal * (h - 52) + pseudoOffset;
        ctx.fillStyle = "#f59e0b";
        ctx.beginPath();
        ctx.arc(px, py, 3, 0, Math.PI * 2);
        ctx.fill();
      }

      ctx.fillStyle = "#94a3b8";
      ctx.font = "10px monospace";
      ctx.fillText("Time (0 → 200 ns)", w / 2 - 40, h - 7);
      ctx.fillText("Normalized PL Intensity", 48, 24);
    }

