    function filterMicroSites(orbitKey) {
      document.querySelectorAll("#orbitFilterGroup .orbit-filter-btn").forEach(btn => {
        const active = btn.getAttribute("data-orbit") === orbitKey;
        btn.className = active
          ? "orbit-filter-btn px-3 py-1.5 rounded-lg text-xs font-semibold bg-indigo-600 text-white"
          : "orbit-filter-btn px-3 py-1.5 rounded-lg text-xs font-semibold bg-slate-900 text-slate-300 border border-slate-800 hover:text-white";
      });
      renderMicroSitesDirectory(orbitKey);
    }

    function mountCustomLabApp() {
      const name = document.getElementById("sdkAppName").value.trim() || "自定义科研微站";
      const domain = document.getElementById("sdkAppDomain").value.trim() || "https://custom.lab.matrixos.edu";
      const orbit = document.getElementById("sdkAppOrbit").value;
      const accepts = document.getElementById("sdkAppAccepts").value.trim();

      const newId = String(MICRO_SITES.length + 1).padStart(2, "0");
      MICRO_SITES.push({
        id: newId,
        orbit: "5",
        orbitName: "开放插槽 · " + orbit,
        name: name,
        domain: domain.replace(/^https?:\/\//, ""),
        source: "高校实验室 SDK 挂载",
        uiStyle: "自定义精密仪器面板",
        ledger: "实验室私有化加密台账",
        desc: "通过 @matrixos/sdk 热插拔接入，支持接收 [" + accepts + "] 跨站虫洞载荷。"
      });

      document.getElementById("sdkMountBadge").innerText = `当前星轨挂载数：18 官方 + ${MICRO_SITES.length - 18} 实验室扩展站`;
      document.getElementById("sdkSlotOutput").innerHTML = `
        <div class="text-emerald-400 font-bold">✓ Manifest 契约校验通过！已成功分配星轨插槽 #${newId}</div>
        <div class="text-cyan-300">• 挂载名称：${name} (${domain})</div>
        <div class="text-slate-300">• SSO 令牌：已接入 MatrixID 全息数字孪生底座</div>
        <div class="text-amber-300">• 虫洞监听：已注册 [${accepts}] 跨站拖拽接收器</div>
        <div class="pt-1"><button onclick="switchMainTab('archipelago'); filterMicroSites('all')" class="px-2.5 py-1 rounded bg-indigo-600 text-white text-[11px]">前往「Tab 3 微站全表」查看新挂载的 #${newId} 微站 →</button></div>
      `;
      renderMicroSitesDirectory("all");
      showToast("成功挂载第 #" + newId + " 号实验室微站：" + name);
    }

    function runFinanceSim() {
      const mau = parseInt(document.getElementById("simMauInput").value);
      const conv = parseFloat(document.getElementById("simConvInput").value);
      const labs = parseInt(document.getElementById("simLabInput").value);

      document.getElementById("simMauLabel").innerText = mau.toLocaleString() + " 人";
      document.getElementById("simConvLabel").innerText = conv.toFixed(1) + "%";
      document.getElementById("simLabLabel").innerText = labs + " 个实验室";

      const totalCost = 15000 + 6000 + Math.round(mau * 1.76);
      const cRev = Math.round(mau * (conv / 100)) * 10 * 12;
      const bRev = labs * 15000;
      const totalRev = cRev + bRev;
      const net = totalRev - totalCost;

      document.getElementById("simTotalCost").innerText = "¥" + totalCost.toLocaleString();
      document.getElementById("simTotalRev").innerText = "¥" + totalRev.toLocaleString();
      const netEl = document.getElementById("simNetProfit");
      netEl.innerText = (net >= 0 ? "+¥" : "-¥") + Math.abs(net).toLocaleString();
      netEl.className = net >= 0
        ? "text-sm font-mono font-bold text-emerald-400 mt-0.5"
        : "text-sm font-mono font-bold text-rose-400 mt-0.5";
    }

